import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/blog/The-public-class/01-%E5%88%9D%E8%AF%86Kitten.html","title":"01-初识Kitten「公益直播课」","lang":"zh-CN","frontmatter":{"title":"01-初识Kitten「公益直播课」","date":"2022-11-06T10:05:27.000Z","author":"AI悦创","isOriginal":true,"icon":"network","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"目录 图形化编程的起源与发展 认识源码编辑器 Kitten 如何利用 Kitten 创建作品 图形化编程的起源与发展 你好，我是悦创。 20 世纪 60 年代，美国麻省理工学院，人工智能实验室的西蒙·派普特 Seymour Papert（1928～2016）专为孩子们设计了一门叫：LOGO 的计算机语言。LOGO 语言是一种易懂易学的结构化程序设计语言...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"01-初识Kitten「公益直播课」\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2022-11-06T10:05:27.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/blog/The-public-class/01-%E5%88%9D%E8%AF%86Kitten.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"01-初识Kitten「公益直播课」"}],["meta",{"property":"og:description","content":"目录 图形化编程的起源与发展 认识源码编辑器 Kitten 如何利用 Kitten 创建作品 图形化编程的起源与发展 你好，我是悦创。 20 世纪 60 年代，美国麻省理工学院，人工智能实验室的西蒙·派普特 Seymour Papert（1928～2016）专为孩子们设计了一门叫：LOGO 的计算机语言。LOGO 语言是一种易懂易学的结构化程序设计语言..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2022-11-06T10:05:27.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":6,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":2}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"efbef5d1f35ab7e1b7546995bcc6cbd5efa55aed","time":1703474570000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"How to create DataFrame with feature importance from XGBClassifier made by GridSearchCV?"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":5.86,"words":1759},"filePathRelative":"blog/The-public-class/01-初识Kitten.md","excerpt":"<h2>目录</h2>\\n<ul>\\n<li>图形化编程的起源与发展</li>\\n<li>认识源码编辑器 Kitten</li>\\n<li>如何利用 Kitten 创建作品</li>\\n</ul>\\n<h2>图形化编程的起源与发展</h2>\\n<p>你好，我是悦创。</p>\\n<p>20 世纪 60 年代，美国麻省理工学院，人工智能实验室的西蒙·派普特 Seymour Papert（1928～2016）专为孩子们设计了一门叫：LOGO 的计算机语言。<strong>LOGO 语言是一种易懂易学的结构化程序设计语言</strong></p>\\n<blockquote>\\n<p><strong>Logo</strong> 是一种计算机<a href=\\"https://zh.m.wikipedia.org/wiki/%E7%A8%8B%E5%BA%8F%E8%AE%BE%E8%AE%A1%E8%AF%AD%E8%A8%80\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">程式设计语言</a>，在 1966 年由<a href=\\"https://zh.m.wikipedia.org/wiki/%E8%A5%BF%E6%91%A9%E7%88%BE%C2%B7%E6%B4%BE%E6%99%AE%E7%89%B9\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">西摩尔·派普特</a>和 Wally Feurzeig 设计[<a href=\\"https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-2\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">2]</a>，Logo 一词源自希腊语<a href=\\"https://zh.m.wikipedia.org/wiki/%E9%82%8F%E5%90%84%E6%96%AF\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">逻各斯</a>（logos）。Logo 是一种<a href=\\"https://zh.m.wikipedia.org/wiki/%E7%9B%B4%E8%AD%AF%E8%AA%9E%E8%A8%80\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">直译语言</a>，和其他语言不同的是，它内置一套海龟绘图（Turtle Graphics）系统[<a href=\\"https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-mit.edu-3\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">3]</a>，通过向海龟发送命令，用户可以直观地学习程序的运行过程，因此很适于初学者特别是儿童学习程序设计。</p>\\n<p>Logo 的<a href=\\"https://zh.m.wikipedia.org/wiki/%E5%8E%9F%E5%9E%8B\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">原型</a>来自另一个计算机语言<a href=\\"https://zh.m.wikipedia.org/wiki/LISP\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">LISP</a>[<a href=\\"https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-cslsPreface-4\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">4]</a>，派普特修改了 LISP 的<a href=\\"https://zh.m.wikipedia.org/wiki/%E8%AF%AD%E6%B3%95\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">语法</a>使其更易于阅读。Logo 常被称作没有括号的 Lisp。Logo 继承了 Lisp 的“表”的概念，所以在函数处理等方面拥有强大的能力，也是有特殊需求的计算机科学家的好帮手[<a href=\\"https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-csls-5\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">5]</a>。</p>\\n</blockquote>","autoDesc":true}`),a={name:`01-初识Kitten.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="目录" tabindex="-1"><a class="header-anchor" href="#目录"><span>目录</span></a></h2><ul><li>图形化编程的起源与发展</li><li>认识源码编辑器 Kitten</li><li>如何利用 Kitten 创建作品</li></ul><h2 id="图形化编程的起源与发展" tabindex="-1"><a class="header-anchor" href="#图形化编程的起源与发展"><span>图形化编程的起源与发展</span></a></h2><p>你好，我是悦创。</p><p>20 世纪 60 年代，美国麻省理工学院，人工智能实验室的西蒙·派普特 Seymour Papert（1928～2016）专为孩子们设计了一门叫：LOGO 的计算机语言。<strong>LOGO 语言是一种易懂易学的结构化程序设计语言</strong></p><blockquote><p><strong>Logo</strong> 是一种计算机<a href="https://zh.m.wikipedia.org/wiki/%E7%A8%8B%E5%BA%8F%E8%AE%BE%E8%AE%A1%E8%AF%AD%E8%A8%80" target="_blank" rel="noopener noreferrer">程式设计语言</a>，在 1966 年由<a href="https://zh.m.wikipedia.org/wiki/%E8%A5%BF%E6%91%A9%E7%88%BE%C2%B7%E6%B4%BE%E6%99%AE%E7%89%B9" target="_blank" rel="noopener noreferrer">西摩尔·派普特</a>和 Wally Feurzeig 设计[<a href="https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-2" target="_blank" rel="noopener noreferrer">2]</a>，Logo 一词源自希腊语<a href="https://zh.m.wikipedia.org/wiki/%E9%82%8F%E5%90%84%E6%96%AF" target="_blank" rel="noopener noreferrer">逻各斯</a>（logos）。Logo 是一种<a href="https://zh.m.wikipedia.org/wiki/%E7%9B%B4%E8%AD%AF%E8%AA%9E%E8%A8%80" target="_blank" rel="noopener noreferrer">直译语言</a>，和其他语言不同的是，它内置一套海龟绘图（Turtle Graphics）系统[<a href="https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-mit.edu-3" target="_blank" rel="noopener noreferrer">3]</a>，通过向海龟发送命令，用户可以直观地学习程序的运行过程，因此很适于初学者特别是儿童学习程序设计。</p><p>Logo 的<a href="https://zh.m.wikipedia.org/wiki/%E5%8E%9F%E5%9E%8B" target="_blank" rel="noopener noreferrer">原型</a>来自另一个计算机语言<a href="https://zh.m.wikipedia.org/wiki/LISP" target="_blank" rel="noopener noreferrer">LISP</a>[<a href="https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-cslsPreface-4" target="_blank" rel="noopener noreferrer">4]</a>，派普特修改了 LISP 的<a href="https://zh.m.wikipedia.org/wiki/%E8%AF%AD%E6%B3%95" target="_blank" rel="noopener noreferrer">语法</a>使其更易于阅读。Logo 常被称作没有括号的 Lisp。Logo 继承了 Lisp 的“表”的概念，所以在函数处理等方面拥有强大的能力，也是有特殊需求的计算机科学家的好帮手[<a href="https://zh.m.wikipedia.org/zh-hans/Logo_(%E7%A8%8B%E5%BA%8F%E8%AF%AD%E8%A8%80)#cite_note-csls-5" target="_blank" rel="noopener noreferrer">5]</a>。</p></blockquote><p>目的在于枯燥的编程语言，形象化给小朋友们带来。</p><figure><img src="/assets/image-20221106101334491-BXCJXRBk.png" alt="image-20221106101334491" tabindex="0" loading="lazy"><figcaption>image-20221106101334491</figcaption></figure><p>希望学生不要机械的记忆事实，希望掌握一些原始语言命令的之后，进行探索学习。通过操作屏幕上的海龟来编写程序。</p><p>强调学生计算思维和有趣的学习体验。</p><p>它具有三部分功能：</p><ol><li>编辑功能「命令与过程的编辑，使学生了解成年人，如何通过文字编辑工作的。」</li><li>驱使海龟移动「绘出各种海龟的功能」</li></ol><figure><img src="/assets/d605f3f483c9dc7ec5bc254e8df26efef780d2d8-BbBmcoEv.png" alt="1968年发明LOGO语言" tabindex="0" loading="lazy"><figcaption>1968年发明LOGO语言</figcaption></figure><ol start="3"><li>制表处理 and 数值处理的功能</li></ol><h2 id="图形化编程语言进一步降低了学生学习编程的门槛" tabindex="-1"><a class="header-anchor" href="#图形化编程语言进一步降低了学生学习编程的门槛"><span>图形化编程语言进一步降低了学生学习编程的门槛</span></a></h2><p>1984年时任乐高 CEO，在电视上看见了西蒙·派普特的采访节目，当时西蒙·派普特在电视中演示实体海龟，乐高 CEO 认为，LOGO 海龟和乐高的产品哲学有相通之处，二者如果能结合起来，肯定是个不错的新产品。</p><p>在与乐高接洽后，西蒙·派普特提出了一个与以往不同的想法。——能够创建一个替代电脑的乐高零部件。一个不仅具有计算功能，又能跟乐高一样小巧，且足够便宜的零部件。在当时，这是一个巨大的挑战。然而，这也将是一个巨大革命式的创新。</p><p>这个设想，直到 1998年才得已实现。那年，乐高发布了全新的可编程机器人产品：</p><figure><img src="/assets/29d07bd5a53ef3b110295b3a67b20918092aa3e7-DZhOCwkK.jpeg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>为了纪念西蒙·派普特，用了他思维风暴的书名，做了注册商标，从此乐高掀起了全球机器人风暴。</p><p>在 80 年代，同样收到 西蒙·派普特启发的还有一个青年记者，一次偶然的机会，他听到了西蒙·派普特的演讲，也由此改变了他对计算机的认知。</p><p>第二年，这个年轻记者拿着 MIT 的奖学金，参加了西蒙·派普特的研讨班，这个青年记者，就是后来的 Scratch 之父米切尔·瑞斯尼克</p><figure><img src="/assets/c803ea59c99262ca8caed9fd1a22e4101ac420cf-DEegGevM.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><img src="/assets/d495756b19759be386f6b79ce877d57fe5ed8089-CSD6Ewy9.jpeg" alt="img" style="zoom:33%;"><p>工具的进步让越来越多的孩子学习编程：</p><figure><img src="/assets/image-20221106121853619-Czz5Uhk7.png" alt="image-20221106121853619" tabindex="0" loading="lazy"><figcaption>image-20221106121853619</figcaption></figure><figure><img src="/assets/image-20221106122204671-Cmnqap2u.png" alt="image-20221106122204671" tabindex="0" loading="lazy"><figcaption>image-20221106122204671</figcaption></figure><p>很多图形化编程平台，都是基于谷歌 Blockly。</p><h2 id="kitten" tabindex="-1"><a class="header-anchor" href="#kitten"><span>Kitten</span></a></h2><figure><img src="/assets/2e589b8eeb71ba2a1386b22944c29d472bff11b9-C3k-t2--.png" alt="源码编辑器 Kitten" tabindex="0" loading="lazy"><figcaption>源码编辑器 Kitten</figcaption></figure><figure><img src="/assets/1-BM3OgeYM.gif" alt="1" tabindex="0" loading="lazy"><figcaption>1</figcaption></figure><p>Kitten 是点猫科技自主研发的一款面向青少儿的图形化编程工具，于 2015 年发布。用鼠标拖到程序模块到脚本区并进行组合，就能进行编程，可以创作游戏、音乐、动画、故事等。</p><figure><img src="/assets/image-20221106122604113-DOa20uow.png" alt="image-20221106122604113" tabindex="0" loading="lazy"><figcaption>image-20221106122604113</figcaption></figure><blockquote><p>其实，很多时候 Scratch 也是足够使用的，我个人还是挺推荐直接使用 Scratch。竞赛啥的，大部分也是直接操作 Scratch。</p></blockquote><ul><li><a href="https://scratch.mit.edu/" target="_blank" rel="noopener noreferrer">https://scratch.mit.edu/</a></li></ul><h2 id="kitten-的不同版本" tabindex="-1"><a class="header-anchor" href="#kitten-的不同版本"><span>Kitten 的不同版本</span></a></h2><ul><li>Kitten2.0：<a href="https://old-kitten.codemao.cn" target="_blank" rel="noopener noreferrer">https://old-kitten.codemao.cn</a></li></ul><figure><img src="/assets/6976028139440d0c9ca38e43765bcd700d062dbc-B7ge6mQ4.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><ul><li>Kitten3.0：<a href="https://kitten.codemao.cn" target="_blank" rel="noopener noreferrer">https://kitten.codemao.cn</a></li></ul><figure><img src="/assets/image-20221106123048519-DLATt1hO.png" alt="image-20221106123048519" tabindex="0" loading="lazy"><figcaption>image-20221106123048519</figcaption></figure><figure><img src="/assets/image-20221106123111628-ByVTNVLo.png" alt="image-20221106123111628" tabindex="0" loading="lazy"><figcaption>image-20221106123111628</figcaption></figure><h2 id="源码编辑器介绍" tabindex="-1"><a class="header-anchor" href="#源码编辑器介绍"><span>源码编辑器介绍</span></a></h2><figure><img src="/assets/image-20221106123200416-_Zatl-bu.png" alt="image-20221106123200416" tabindex="0" loading="lazy"><figcaption>image-20221106123200416</figcaption></figure><ul><li>事件：程序（效果）的开始、暂停和结束</li><li>控制：控制运行流程</li><li>侦测：返回侦测的结果</li><li>数据：变量、列表</li><li>函数：自定义</li></ul><p><strong>相似功能的积木放在同一个分类里，并且同一个分类下的积木颜色相同。</strong></p><h2 id="如何利用-kitten-创建作品" tabindex="-1"><a class="header-anchor" href="#如何利用-kitten-创建作品"><span>如何利用 Kitten 创建作品</span></a></h2><ol><li>新建空白作品</li><li>添加背景</li><li>添加角色</li><li>添加声音</li></ol><figure><img src="/assets/e2bc5100df1fb2db5ec6016211b022651d080178-20221106124900559-DF86sEzy.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><blockquote><p>01.脚本区-声音；02.音乐画板-创作-保存；0.3素材库</p></blockquote><ol start="5"><li>画板绘制图形「画板-绘制-保存（角色）」</li><li>添加造型</li></ol><figure><img src="/assets/339fe6071043ef29b0fe4f894d89e2cea7ba3bb3-DPGDG71Q.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><blockquote><p>脚本区-造型区-添加/绘制/导入</p></blockquote><ol start="7"><li>保存和分享</li></ol><figure><img src="/assets/2a5e50c5f206c58df1490da50c10f0325761e035-CCHyQTrA.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><figure><img src="/assets/28373472cfb2dc0ae1bf8a4d6b56aaf8b02f24c9-B2HrVhqH.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><figure><img src="/assets/e7384b35e09969d80e4b56c4fd76b2806ad9f439-C8dvfPqv.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><blockquote><p>菜单栏-手机图标-扫码-分享作品</p></blockquote><ol start="8"><li>打开与拖入</li></ol><figure><img src="/assets/75d7f714e79ce6aa830d6c51ff3c72768c64520e-k6jIylHj.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><blockquote><p>菜单栏-文件-打开/打开本地作品</p></blockquote><figure><img src="/assets/97f31663c9baeab04aa06b2cc51808a6bcdaeafa-r0Rcpm93.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><blockquote><p>快捷操作-拖入图片/bcm文件</p></blockquote><h2 id="练一练" tabindex="-1"><a class="header-anchor" href="#练一练"><span>练一练</span></a></h2><p>新建空白作品，添加任意角色和背景，给角色添加脚本，实现任意效果</p><figure><img src="/assets/f52c7ce5344bdcd92953f528057aeaf762633718-DdugCYe-.gif" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><h2 id="课程回放-课程资源" tabindex="-1"><a class="header-anchor" href="#课程回放-课程资源"><span>课程回放&amp;课程资源</span></a></h2><ul><li><a href="https://www.yuque.com/aiyuechuang/scratch" target="_blank" rel="noopener noreferrer">https://www.yuque.com/aiyuechuang/scratch</a></li></ul><p>欢迎关注我公众号：AI悦创，有更多更好玩的等你发现！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,71)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};